'use client';

import type { WorkspaceTaskRecurrenceState } from '@tuturuuu/internal-api/task-recurrence';
import { Pause, Repeat } from '@tuturuuu/icons';
import { Badge } from '@tuturuuu/ui/badge';
import { cn } from '@tuturuuu/utils/format';
import { useTranslations } from 'next-intl';
import type { Ref } from 'react';

interface TaskRecurrenceBadgeProps {
  state: WorkspaceTaskRecurrenceState;
  /** The schedule summary, when the reader may see it. */
  summary?: string;
  size?: 'sm' | 'md';
  ref?: Ref<HTMLSpanElement>;
  className?: string;
}

/** Marks a task generated by a series. The visible text stays short; the
 * accessible name carries the state and, when known, the schedule. */
export function TaskRecurrenceBadge({
  state,
  summary,
  size = 'sm',
  ref,
  className,
}: TaskRecurrenceBadgeProps) {
  const t = useTranslations('ws-task-boards.recurrence');
  const paused = state === 'paused';
  const ended = state === 'ended';
  const stateLabel = paused
    ? t('state_paused')
    : ended
      ? t('state_ended')
      : null;
  const label = [t('badge'), summary, stateLabel].filter(Boolean).join(', ');
  const Icon = paused ? Pause : Repeat;

  return (
    <Badge
      ref={ref}
      variant="secondary"
      role="img"
      aria-label={label}
      title={label}
      data-testid="task-recurrence-badge"
      data-state={state}
      className={cn(
        'shrink-0 gap-1 border border-border bg-secondary text-muted-foreground',
        size === 'sm' ? 'h-5 px-1.5 text-[10px]' : 'h-6 px-2 text-xs',
        className
      )}
    >
      <Icon
        aria-hidden="true"
        className={size === 'sm' ? 'size-2.5' : 'size-3'}
      />
      <span aria-hidden="true" className="truncate">
        {summary ?? stateLabel ?? t('badge_short')}
      </span>
    </Badge>
  );
}
